CREATE TABLE legal_document (
    document_key VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY,
    draft_json JSON NOT NULL,
    requires_reconsent BOOLEAN NOT NULL DEFAULT FALSE,
    published_revision BIGINT NOT NULL DEFAULT 1,
    lock_version BIGINT NOT NULL DEFAULT 0,
    updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT ck_legal_document_key CHECK (document_key IN ('privacy','terms')),
    CONSTRAINT ck_legal_document_version CHECK (lock_version >= 0 AND published_revision > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE legal_document_publication (
    document_key VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    revision BIGINT NOT NULL,
    consent_revision BIGINT NOT NULL,
    content_json JSON NOT NULL,
    published_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (document_key, revision),
    CONSTRAINT fk_legal_document_publication FOREIGN KEY (document_key) REFERENCES legal_document(document_key),
    CONSTRAINT ck_legal_document_publication_revision CHECK (revision > 0 AND consent_revision > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO legal_document(document_key,draft_json) VALUES ('privacy',CONVERT( USING utf8mb4));
INSERT INTO legal_document(document_key,draft_json) VALUES ('terms',CONVERT( USING utf8mb4));

INSERT INTO legal_document_publication(document_key,revision,consent_revision,content_json) SELECT document_key,1,1,draft_json FROM legal_document;
